import{z as t,x as i,o as l,c as n,q as B,j as e,D as a,d as A,s,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"RL 训练系统收束","description":"","frontmatter":{"title":"RL 训练系统收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-map.md","filePath":"llm/rlsys-map.md","lastUpdated":1791413859000}'),m={name:"llm/rlsys-map.md"};function p(h,E,d,F,C,f){const r=i("Mermaid");return l(),n("div",null,[E[2]||(E[2]=B('<h1 id="rl-训练系统收束" tabindex="-1">RL 训练系统收束 <a class="header-anchor" href="#rl-训练系统收束" aria-label="Permalink to &quot;RL 训练系统收束&quot;">​</a></h1><div class="epigraph"><p>把一台 RL 训练机拆开，只剩两条不变量：样本永远知道自己出自哪个版本，仪表永远独立于被监控的对象。</p><footer>—— 据 Sheng 等 HybridFlow（EuroSys 2025）与开源框架文档整理</footer></div><p><a href="/llm/rlsys-production-ablation">上一课</a>用消融纪律把结论钉在可比的地基上，本课程到此收束。三个单元走过的路：架构（<a href="/llm/rlsys-rollout-arch">rollout 引擎的架构</a>、<a href="/llm/rlsys-reward-serving">奖励模型的服务化</a>、<a href="/llm/rlsys-refmodel-kl">引用模型与 KL 的管理</a>）；工程（<a href="/llm/rlsys-replay-batching">经验回放与批处理</a>、<a href="/llm/rlsys-inference-in-loop">推理引擎在 RL 循环里</a>、<a href="/llm/rlsys-multiturn-env">多轮 RL 的环境工程</a>、<a href="/llm/rlsys-async-debug">异步 RL 的系统调试</a>）；监控与生产（<a href="/llm/rlsys-hacking-monitor">Reward hacking 的监控</a>、<a href="/llm/rlsys-eval-in-loop">评测在环</a>、<a href="/llm/rlsys-cost-vs-sft">成本：RL 相对 SFT</a>、<a href="/llm/rlsys-failure-catalog">失败模式清单</a>、<a href="/llm/rlsys-production-ablation">生产案例与消融管理</a>）。本课把零件装回整机，并给算法课程交一份分账清单：系统替你扛了什么，没扛什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束课的问题是：十三课能不能压缩成更少的命题？如果每课是一个零件说明书，收束课要给出整机的原理图——哪些是承载一切的不变量，哪些是可替换的实现选择，哪些账单永远要有人付。压缩的判据是：删掉一条命题后，机器会在哪类事故里坏，就把它归到哪一类。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>整机原理图一条主线、三条不变量。主线是数据流：提示池喂 <a href="/llm/rlsys-rollout-arch">rollout 引擎的架构</a>生成经验（序列加行为 logprob 加版本号），<a href="/llm/rlsys-reward-serving">奖励模型的服务化</a>补分数列，<a href="/llm/rlsys-replay-batching">经验回放与批处理</a>组批过滤，训练器更新，权重经同步回生成端。不变量一，版本对齐：行为 logprob、奖励、KL 的分母都绑定明确版本，<a href="/llm/rlsys-async-debug">异步 RL 的系统调试</a>的探针守着它。不变量二，仪表独立：金标与监控不进训练环，<a href="/llm/rlsys-eval-in-loop">评测在环</a>的卫生闸门守着它。不变量三，预算显式：显存、上下文、staleness、卡时都要写成配置与水位，<a href="/llm/rlsys-failure-catalog">失败模式清单</a>的水位告警守着它们。<a href="/llm/rlsys-refmodel-kl">引用模型与 KL 的管理</a>站在算法与系统的接缝上：跑道多宽是算法决定，跑道刻进显存与调度是系统执行。</p><p><span class="marginnote">直觉类比：把系统想成一条流水线，版本号就是每件半成品上挂的工单——无论它流到打分、组批还是更新的工位，工单都注明出自哪版模具。丢了工单的流水线照样转，只是没人说得清成品是谁做的，出了错也没法追责。</span></p><p><span class="marginnote">判据的用法：删掉「版本对齐」，坏法是静默离策略（<a href="/llm/truncated-importance-sampling">截断重要性采样</a>救得回一半）；删掉「仪表独立」，坏法是守门人被收买；删掉「预算显式」，坏法是长尾一步顶爆显存。三类坏法对应三类断言，这就是清单的由来。</span></p>',9)),(l(),e(o,null,{default:a(()=>[s(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%8F%90%E7%A4%BA%E6%B1%A0%EF%BC%88%E4%B8%8E%E8%AF%84%E6%B5%8B%E9%9B%86%E9%9A%94%E7%A6%BB%EF%BC%89%22%5D%20--%3E%20ENG%5B%22rollout%20%E5%BC%95%E6%93%8E%EF%BC%88v_k%EF%BC%89%22%5D%0A%20%20ENG%20--%3E%20SEQ%5B%22%E5%BA%8F%E5%88%97%20%2B%20%E8%A1%8C%E4%B8%BA%20logprob%20%2B%20%E7%89%88%E6%9C%AC%22%5D%0A%20%20SEQ%20--%3E%20RS%5B%22%E6%89%93%E5%88%86%E6%9C%8D%E5%8A%A1%EF%BC%9ARM%20%E6%88%96%E9%AA%8C%E8%AF%81%E5%99%A8%EF%BC%88v_j%EF%BC%89%22%5D%0A%20%20RS%20--%3E%20BUF%5B%22%E7%BB%8F%E9%AA%8C%E7%BC%93%E5%86%B2%EF%BC%9A%E7%BB%84%E6%89%B9%2F%E8%BF%87%E6%BB%A4%2F%E7%99%BD%E5%8C%96%2F%E6%89%93%E5%8C%85%22%5D%0A%20%20BUF%20--%3E%20TR%5B%22%E8%AE%AD%E7%BB%83%E5%99%A8%EF%BC%88%2B%20%E5%BC%95%E7%94%A8%E6%A8%A1%E5%9E%8B%20KL%EF%BC%89%22%5D%0A%20%20TR%20--%3E%7C%22%E5%8E%9F%E5%AD%90%E5%90%8C%E6%AD%A5%EF%BC%8C%E7%89%88%E6%9C%AC%20%2B1%22%7C%20ENG%0A%20%20MON%5B%22%E7%9B%91%E6%8E%A7%EF%BC%9A%E4%BA%A4%E5%8F%89%E5%AF%B9%E7%85%A7%2F%E6%BC%82%E7%A7%BB%2F%E6%B0%B4%E4%BD%8D%22%5D%20-.-%3E%20TR%0A%20%20EVAL%5B%22%E8%AF%84%E6%B5%8B%E5%9C%A8%E7%8E%AF%EF%BC%9A%E4%B8%89%E5%B1%82%E6%A0%88%20%2B%20%E5%9B%9E%E5%BD%92%E9%97%A8%22%5D%20-.-%3E%20TR%0A%20%20TR%20--%3E%20CKPT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%20%E2%86%92%20%E6%B6%88%E8%9E%8D%E6%A1%A3%E6%A1%88%20%E2%86%92%20%E9%85%8D%E6%96%B9%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>系统与算法的分账。系统扛走的：迭代成本——引擎、共置与异步把闲置压掉；静默错误——探针、断言与清单把几周量级的事故压到分钟级；统计混淆——消融纪律把假提升挡在门外。系统扛不走的：奖励设计，<a href="/llm/rm-overoptimization">RM 过优化与 Goodhart</a> 的拐点不因系统变快而消失；算法方差，<a href="/llm/reinforce-variance">REINFORCE 与方差</a> 的账仍在策略梯度里；任务与分布的选择——环境即 MDP，<a href="/llm/rlsys-multiturn-env">多轮 RL 的环境工程</a>里那句「环境设计就是奖励设计」是本课程与算法课程之间的双向桥。</p><p><span class="marginnote">「引用模型 KL」翻译成大白话：KL 是一把尺子，量当前策略和出发时的参考模型差了多远。跑道比喻就是为它画的——预算多宽（允许走多远）是算法的决定，把尺子插进显存与调度里按时测、别忘测，是系统的执行。</span></p><p>开源系统（<a href="/llm/verl-hybridflow">verl 与 HybridFlow</a>、<a href="/llm/openrlhf">OpenRLHF</a>、<a href="/llm/slime-rl">slime 轻量 RL 框架</a>）把零件做成了可安装的形态，但配方——隐旋钮取值、卫生闸门、监控面板——仍然只有自己能建。</p><p><span class="marginnote">常见误区：初学者容易以为「系统够快就能弥补算法问题」——方向错了，快只放大速度、不纠正方向。奖励设计错了，系统越快、烧卡越多、离目标越远。系统承诺的是「又快又不出静默故障」，从不承诺「学对东西」。</span></p>',5)),(l(),e(o,null,{default:a(()=>[s(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E6%89%9B%E5%BE%97%E8%B5%B0%22%5D%20--%3E%20C1%5B%22%E8%BF%AD%E4%BB%A3%E6%88%90%E6%9C%AC%EF%BC%9A%E5%BC%95%E6%93%8E%20%2F%20%E5%85%B1%E7%BD%AE%20%2F%20%E5%BC%82%E6%AD%A5%E5%8E%8B%E6%8E%89%E9%97%B2%E7%BD%AE%22%5D%0A%20%20SYS%20--%3E%20C2%5B%22%E9%9D%99%E9%BB%98%E9%94%99%E8%AF%AF%EF%BC%9A%E6%8E%A2%E9%92%88%E6%96%AD%E8%A8%80%E6%8A%8A%E5%91%A8%E7%BA%A7%E4%BA%8B%E6%95%85%E5%8E%8B%E5%88%B0%E5%88%86%E9%92%9F%E7%BA%A7%22%5D%0A%20%20SYS%20--%3E%20C3%5B%22%E7%BB%9F%E8%AE%A1%E6%B7%B7%E6%B7%86%EF%BC%9A%E6%B6%88%E8%9E%8D%E7%BA%AA%E5%BE%8B%E6%8C%A1%E4%BD%8F%E5%81%87%E6%8F%90%E5%8D%87%22%5D%0A%20%20ALG%5B%22%E7%B3%BB%E7%BB%9F%E6%89%9B%E4%B8%8D%E8%B5%B0%22%5D%20--%3E%20A1%5B%22%E5%A5%96%E5%8A%B1%E8%AE%BE%E8%AE%A1%EF%BC%9AGoodhart%20%E6%8B%90%E7%82%B9%E7%85%A7%E5%9C%A8%22%5D%0A%20%20ALG%20--%3E%20A2%5B%22%E7%AE%97%E6%B3%95%E6%96%B9%E5%B7%AE%EF%BC%9A%E4%BB%8D%E5%9C%A8%E7%AD%96%E7%95%A5%E6%A2%AF%E5%BA%A6%E9%87%8C%22%5D%0A%20%20ALG%20--%3E%20A3%5B%22%E4%BB%BB%E5%8A%A1%E4%B8%8E%E5%88%86%E5%B8%83%E9%80%89%E6%8B%A9%EF%BC%9A%E7%8E%AF%E5%A2%83%E5%8D%B3%20MDP%22%5D%0A%20%20A1%20-.-%3E%7C%22%E7%B3%BB%E7%BB%9F%E5%86%8D%E5%BF%AB%E4%B9%9F%E6%95%91%E4%B8%8D%E4%BA%86%E9%94%99%E5%A5%96%E5%8A%B1%22%7C%20BAD%5B%22%E6%9B%B4%E5%BF%AB%E5%88%B0%E8%BE%BE%E9%94%99%E8%AF%AF%E7%9A%84%E7%BB%88%E7%82%B9%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程的边界即 RL 训练系统的边界：它假设奖励可定义（RM、验证器或人审），假设算力买得到经验。奖励写不成的域（无金标、人审太贵）与经验太贵的域（环境慢、轨迹长）里，这台机器的账算不平——那是算法与产品的问题，不是系统的问题。反向的告诫同样成立：系统再好也救不了错的奖励，只会让你更快地到达错误的终点。本课程到此收束，机器交回给写配方的人。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一条主线：生成 → 打分 → 组批 → 更新 → 同步回生成端；版本号全程随行。</li><li>三条不变量：版本对齐、仪表独立、预算显式；探针、卫生闸门、水位是各自的守卫。</li><li>分账：系统扛迭代成本、静默错误与统计混淆；扛不走奖励设计、算法方差与任务选择。</li><li>环境设计就是奖励设计：系统课程与算法课程在这句话上对接。</li><li>本课程收束：机器可安装，配方需自建；出处口径为 HybridFlow（EuroSys 2025）与 verl、OpenRLHF、slime 的文档实现。</li></ul>',4))])}const u=t(m,[["render",p]]);export{c as __pageData,u as default};
